import{_ as n,a0 as o,w as p,s as d,I as s,x as e,a1 as a,A as l,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"终端基础：在 Linux 中复制文件和目录 | LCTT x X-CMD","titleTemplate":false,"description":"终端基础：在 Linux 中复制文件和目录 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"终端基础：在 Linux 中复制文件和目录 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"终端基础：在 Linux 中复制文件和目录 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230329.2 ⭐️ Linux Terminal Basics 7 Copy Files and Directories in Linux","title":"终端基础：在 Linux 中复制文件和目录","tag":"202307","desc":""},"relativePath":"202307/20230329.2 ⭐️ Linux Terminal Basics 7 Copy Files and Directories in Linux.md","filePath":"[post].md"}'),c={name:"202307/20230329.2 ⭐️ Linux Terminal Basics 7 Copy Files and Directories in Linux.md"};function h(u,i,g,m,k,f){const t=o("Link");return p(),d("div",null,[i[22]||(i[22]=s("h1",{id:"终端基础-在-linux-中复制文件和目录",tabindex:"-1"},[e("终端基础：在 Linux 中复制文件和目录 "),s("a",{class:"header-anchor",href:"#终端基础-在-linux-中复制文件和目录","aria-label":"Permalink to “终端基础：在 Linux 中复制文件和目录”"},"​")],-1)),i[23]||(i[23]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202307/31/220802ozpf3gt9gpj2pp0f.jpg",alt:""})],-1)),i[24]||(i[24]=s("blockquote",null,[s("p",null,"在终端基础知识系列的这一部分中，学习如何在 Linux 中使用命令行复制文件和目录。")],-1)),i[25]||(i[25]=s("p",null,"复制文件是你经常执行的最基本但最重要的任务之一。",-1)),i[26]||(i[26]=s("p",null,[e("Linux 有一个专门的 "),s("code",null,"cp"),e(" 命令用于复制文件和目录（文件夹）。")],-1)),i[27]||(i[27]=s("p",null,"在终端基础知识系列的这一部分中，你将学习在终端中复制文件和文件夹。",-1)),s("blockquote",null,[i[6]||(i[6]=s("p",null,"📋 回想一下，以下是你迄今为止在本终端基础知识系列中所学到的内容：",-1)),s("ul",null,[s("li",null,[a(t,{href:"https://itsfoss.com/change-directories/"},{default:l(()=>[...i[0]||(i[0]=[e("更改目录",-1)])]),_:1})]),s("li",null,[a(t,{href:"https://linux.cn/article-15595-1.html"},{default:l(()=>[...i[1]||(i[1]=[e("创建新目录",-1)])]),_:1})]),s("li",null,[a(t,{href:"https://itsfoss.com/list-directory-content/"},{default:l(()=>[...i[2]||(i[2]=[e("列出目录内容",-1)])]),_:1})]),s("li",null,[a(t,{href:"https://linux.cn/article-15643-1.html"},{default:l(()=>[...i[3]||(i[3]=[e("创建文件",-1)])]),_:1})]),s("li",null,[a(t,{href:"https://itsfoss.com/view-file-contents/"},{default:l(()=>[...i[4]||(i[4]=[e("读取文件",-1)])]),_:1})]),s("li",null,[a(t,{href:"https://linux.cn/article-15809-1.html"},{default:l(()=>[...i[5]||(i[5]=[e("删除文件和目录",-1)])]),_:1})])])]),i[28]||(i[28]=r('<p>让我们继续该系列的第七章。</p><h3 id="在-linux-命令行中复制文件" tabindex="-1">在 Linux 命令行中复制文件 <a class="header-anchor" href="#在-linux-命令行中复制文件" aria-label="Permalink to “在 Linux 命令行中复制文件”">​</a></h3><p>让我向你展示一些复制文件的示例。</p><h4 id="将文件复制到另一个目录" tabindex="-1">将文件复制到另一个目录 <a class="header-anchor" href="#将文件复制到另一个目录" aria-label="Permalink to “将文件复制到另一个目录”">​</a></h4><p>要将一个文件复制到另一目录，你所要做的就是遵循给定的命令语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp 源文件 目标目录</span></span></code></pre></div><p>例如，在这里，我将名为 <code>Hello.txt</code> 的文件复制到名为 <code>Tux</code> 的目录中：</p><p><img src="https://itsfoss.com/content/images/2023/02/copy-file-to-another-directory-in-linux-command-line.png" alt="copy file to another directory in linux command line"></p><p>正如你所看到的，文件已成功复制到 <code>Tux</code> 目录中。</p><h4 id="复制文件但重命名" tabindex="-1">复制文件但重命名 <a class="header-anchor" href="#复制文件但重命名" aria-label="Permalink to “复制文件但重命名”">​</a></h4><p>你可以选择在复制文件时重命名该文件。只需为“目标文件”指定一个不同的名称即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp 源文件 改名的文件</span></span></code></pre></div><p>作为参考，在这里，我将名为 <code>Hello.txt</code> 的文件复制到同一目录，并将其重命名为 <code>Renamed_Hello.txt</code>：</p><p><img src="https://itsfoss.com/content/images/2023/02/rename-a-file-while-copying-in-a-same-directory-in-linux-terminal.png" alt="rename a file while copying in a same directory in linux terminal"></p><p>为什么要这么做？ 比如说，你必须编辑配置文件。一个好的做法是在编辑配置文件之前在同一位置对其进行备份。这样，如果事情没有按计划进行，你可以恢复到旧配置。</p><h4 id="将多个文件复制到另一个位置" tabindex="-1">将多个文件复制到另一个位置 <a class="header-anchor" href="#将多个文件复制到另一个位置" aria-label="Permalink to “将多个文件复制到另一个位置”">​</a></h4><p>要将多个文件复制到另一个目录，请按以下方式执行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp File1 File2 File3 FileN Target_directory</span></span></code></pre></div><p>在这里，我将多个文件复制到新位置。</p><p><img src="https://itsfoss.com/content/images/2023/02/copy-multiple-files-using-the-cp-command-in-linux.png" alt="copy multiple files using the cp command in linux"></p><blockquote><p>📋 当你复制多个文件时，仅使用 <code>cp</code> 命令无法重命名它们。</p></blockquote><h4 id="复制时处理重复文件" tabindex="-1">复制时处理重复文件 <a class="header-anchor" href="#复制时处理重复文件" aria-label="Permalink to “复制时处理重复文件”">​</a></h4><p>默认情况下，如果目标目录中存在同名文件，<code>cp</code> 命令将覆盖该文件。</p><p>为了避免覆盖，你可以在 cp 命令中使用 <code>-n</code> 选项，它不会覆盖现有文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -n 源文件 目标目录</span></span></code></pre></div><p>例如，在这里，我尝试复制目标目录中已有的两个文件，并使用 <code>-v</code> 选项来展示该命令正在执行的操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -n -v itsFOSS.txt LHB.txt LU.txt ~/Tux</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/how-not-to-override-files-while-copying-in-linux-using-the-cp-command.png" alt="how not to override files while copying in linux using the cp command"></p><h4 id="交互式复制文件" tabindex="-1">交互式复制文件 <a class="header-anchor" href="#交互式复制文件" aria-label="Permalink to “交互式复制文件”">​</a></h4><p>但是，当你想要覆盖某些文件，而某些文件应该保持不变时该怎么办？</p><p>好吧，你可以使用 <code>-i</code> 选项在交互模式下使用 <code>cp</code> 命令，它每次都会询问你是否应该覆盖该文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -i 源文件 目标目录</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/how-to-use-cp-command-in-interactive-mode.png" alt="how to use cp command in interactive mode"></p><blockquote><p>🖥️ 自己练习上述所有示例。你已经了解如何创建文件和文件夹，因此请重新创建所有内容。</p></blockquote><h3 id="在-linux-命令行中复制目录" tabindex="-1">在 Linux 命令行中复制目录 <a class="header-anchor" href="#在-linux-命令行中复制目录" aria-label="Permalink to “在 Linux 命令行中复制目录”">​</a></h3><p><code>mkdir</code> 命令用于创建新目录，<code>rmdir</code> 命令用于删除（空）目录。但没有用于复制目录的 <code>cpdir</code> 命令。</p><p>你必须使用相同的 <code>cp</code> 命令，但使用递归选项 <code>-r</code> 将目录及其所有内容复制到另一个位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r 源目录 目标目录</span></span></code></pre></div><p>例如，在这里，我将名为 <code>IF</code> 的目录复制到 <code>LHB</code>：</p><p><img src="https://itsfoss.com/content/images/2023/02/how-to-copy-a-directory-in-linux-command-line.png" alt="how to copy a directory in linux command line"></p><p>但它复制了整个目录。🤨</p><p>那么，当你只想复制目录内容而不是目录本身时该怎么办？</p><p>你可以执行以下操作：</p><h4 id="仅复制目录的内容-不是目录" tabindex="-1">仅复制目录的内容（不是目录） <a class="header-anchor" href="#仅复制目录的内容-不是目录" aria-label="Permalink to “仅复制目录的内容（不是目录）”">​</a></h4><p>要仅复制目录的内容，而不复制目录本身，请在源目录名称的末尾附加 <code>/.</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r 源目录/. 目标目录</span></span></code></pre></div><p>在这里，我想复制名为 <code>IF</code> 的目录的内容，其中包含以下三个文件：</p><p><img src="https://itsfoss.com/content/images/2023/02/check-the-file-contents-of-directory-using-the-tree-command.png" alt="check the file contents of directory using the tree command"></p><p>我将执行以下命令将 <code>IF</code> 目录的文件内容复制到 <code>LHB</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r IF/. LHB</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/copy-the-file-contents-of-directory-not-a-directory-itself-in-linux-command-line.png" alt="copy the file contents of directory not a directory itself in linux command line"></p><p>你还可以在此处使用 <code>源目录/*</code> 。</p><h4 id="复制多个目录" tabindex="-1">复制多个目录 <a class="header-anchor" href="#复制多个目录" aria-label="Permalink to “复制多个目录”">​</a></h4><p>要复制多个目录，你必须按以下方式执行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r 目录1 目录2 目录3 目录N 目标目录</span></span></code></pre></div><p>例如，在这里，我将两个名为 <code>IF</code> 和 <code>LU</code> 的目录复制到 <code>LHB</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r IF LU ~/LHB</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/copy-multiple-directories-using-the-cp-command-in-linux-command-line.png" alt="copy multiple directories using the cp command in linux command line"></p><p>当你想要从多个目录复制文件但不复制目录本身时，你可以执行相同的操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r 目录1/. 目录2/. 目录3/. 目录N/. 目标目录</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/copy-files-from-multiple-directories-but-not-directories-their-self-using-the-cp-command.png" alt="copy files from multiple directories but not directories their self using the cp command"></p><blockquote><p>🖥️ 你还可以像重命名文件一样重命名目录。</p></blockquote><h3 id="测试你的知识" tabindex="-1">测试你的知识 <a class="header-anchor" href="#测试你的知识" aria-label="Permalink to “测试你的知识”">​</a></h3><p>现在，让我们看看你对到目前为止所学到的知识还记得多少。</p><ul><li>创建一个名为 <code>copy_practice</code> 的目录。</li><li>将文件 <code>/etc/services</code> 复制到这个新创建的文件夹。</li><li>在此目录下创建一个名为 <code>secrets</code> 的文件夹，并将文件 <code>/etc/passwd</code> 和 <code>/etc/services</code> 复制到其中。</li><li>将 <code>copy_practice</code> 中的 <code>services</code> 文件复制到 <code>secrets</code> 文件夹中，但不要覆盖它。</li><li>将 <code>secrets</code> 文件夹复制到你的主目录。</li><li>删除 <code>secrets</code> 和 <code>copy_practice</code> 目录。</li></ul><p>这会给你一些练习。</p><p>到目前为止进展顺利。你已经学到了很多东西。在下一章中，你将了解如何使用 <code>mv</code> 命令移动文件和文件夹。</p><hr>',68)),s("p",null,[i[8]||(i[8]=e("via: ",-1)),a(t,{href:"https://itsfoss.com/copy-files-directory-linux/"},{default:l(()=>[...i[7]||(i[7]=[e("https://itsfoss.com/copy-files-directory-linux/",-1)])]),_:1})]),s("p",null,[i[13]||(i[13]=e("作者：",-1)),a(t,{href:"https://itsfoss.com/author/sagar/"},{default:l(()=>[...i[9]||(i[9]=[e("Sagar Sharma",-1)])]),_:1}),i[14]||(i[14]=e(" 选题：",-1)),a(t,{href:"https://github.com/lkxed/"},{default:l(()=>[...i[10]||(i[10]=[e("lkxed",-1)])]),_:1}),i[15]||(i[15]=e(" 译者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:l(()=>[...i[11]||(i[11]=[e("geekpi",-1)])]),_:1}),i[16]||(i[16]=e(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:l(()=>[...i[12]||(i[12]=[e("wxy",-1)])]),_:1})]),s("p",null,[i[19]||(i[19]=e("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[17]||(i[17]=[e("LCTT",-1)])]),_:1}),i[20]||(i[20]=e(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:l(()=>[...i[18]||(i[18]=[e("Linux中国",-1)])]),_:1}),i[21]||(i[21]=e(" 荣誉推出",-1))])])}const C=n(c,[["render",h]]);export{y as __pageData,C as default};
